{
    shenlvbu->setFlags("ShenfenUsing");
    room->broadcastSkillInvoke("shenfen");
    QString name = "shenlvbu";
    if (shenlvbu->getGeneralName() != "shenlvbu" && (shenlvbu->getGeneralName() == "sp_shenlvbu" || shenlvbu->getGeneral2Name() == "sp_shenlvbu"))
        name = "sp_shenlvbu";

